function Write-SysLog {
    param(
        [string]$Message,
        [string]$Level   = 'INFO',
        [string]$LogPath = "$env:TEMP\DSI_SysLog.txt"
    )
    $ts    = (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')
    $entry = "[$ts] [$Level] $Message"
    $color = switch ($Level) {
        'ERROR' { 'Red'     }
        'WARN'  { 'Yellow'  }
        'AUDIT' { 'Cyan'    }
        default { 'Green'   }
    }
    Write-Host $entry -ForegroundColor $color
    Add-Content -Path $LogPath -Value $entry -Encoding UTF8
}

public static void WriteLog(string message, string level = "INFO") {
    string ts    = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
    string entry = $"[{ts}] [{level}] {message}";
    ConsoleColor color = level switch {
        "ERROR" => ConsoleColor.Red,
        "WARN"  => ConsoleColor.Yellow,
        "AUDIT" => ConsoleColor.Cyan,
        _       => ConsoleColor.Green
    };
    Console.ForegroundColor = color;
    Console.WriteLine(entry);
    Console.ResetColor();
    string logPath = Path.Combine(Path.GetTempPath(), "DSI_SysLog.txt");
    File.AppendAllText(logPath, entry + Environment.NewLine);
}

public static string GenerateJwtToken(string subject, string secretKey, int expiresInMinutes = 60, Dictionary<string, object> customClaims = null) {
    var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
    var creds = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);
    var claims = new List<Claim> { new Claim(JwtRegisteredClaimNames.Sub, subject), new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString()) };
    if (customClaims != null) {
        foreach (var kv in customClaims) claims.Add(new Claim(kv.Key, kv.Value.ToString()));
    }
    var token = new JwtSecurityToken(issuer: "DSI-OMNI", audience: "DSI-CLIENTS", claims: claims, expires: DateTime.UtcNow.AddMinutes(expiresInMinutes), signingCredentials: creds);
    return new JwtSecurityTokenHandler().WriteToken(token);
}

public static decimal CalculateCompoundInterestDecimal(decimal principal, decimal annualRate, int timesCompounded, decimal years) {
    decimal baseValue = 1 + (annualRate / timesCompounded);
    decimal exponent = timesCompounded * years;
    decimal finalAmount = principal * (decimal)Math.Pow((double)baseValue, (double)exponent);
    return Math.Round(finalAmount, 2, MidpointRounding.AwayFromZero);
}

public static float[] SimdVectorAdd(float[] arrayA, float[] arrayB) {
    if (arrayA.Length != arrayB.Length) throw new ArgumentException("Arrays must be same length");
    float[] result = new float[arrayA.Length];
    int vectorSize = Vector<float>.Count;
    int i = 0;
    for (; i <= arrayA.Length - vectorSize; i += vectorSize) {
        Vector<float> vA = new Vector<float>(arrayA, i);
        Vector<float> vB = new Vector<float>(arrayB, i);
        (vA + vB).CopyTo(result, i);
    }
    for (; i < arrayA.Length; i++) {
        result[i] = arrayA[i] + arrayB[i];
    }
    return result;
}

function Set-ProcessCpuAffinity {
    param([int]$ProcessId, [int]$CoreMask)
    try {
        $proc = Get-Process -Id $ProcessId -ErrorAction Stop
        $proc.ProcessorAffinity = [IntPtr]$CoreMask
        Write-SysLog "Affinité CPU du processus $ProcessId définie sur $CoreMask"
        return $true
    } catch {
        Write-SysLog "Échec affinité CPU pour $ProcessId : $_" -Level 'ERROR'
        return $false
    }
}

public static Dictionary<string, string> GenerateEthereumWallet(bool includeTestnet = false) {
    var privateKeyBytes = new byte[32];
    using var rng = RandomNumberGenerator.Create();
    rng.GetBytes(privateKeyBytes);
    var privateKey = "0x" + BitConverter.ToString(privateKeyBytes).Replace("-", "").ToLower();
    // Simulation de la dérivation d'adresse via ECDSA (nécessite Nethereum en prod)
    var address = "0x" + Convert.ToHexString(SHA256.HashData(privateKeyBytes)).Substring(24).ToLower();
    return new Dictionary<string, string> { { "PrivateKey", privateKey }, { "Address", address } };
}

public static bool SerializeModelToOnnx(byte[] modelData, string outputPath, int opsetVersion = 15) {
    try {
        // En production : utiliser Microsoft.ML.OnnxRuntime ou ONNX.NET
        File.WriteAllBytes(outputPath, modelData);
        WriteLog($"Modèle exporté au format ONNX (Opset {opsetVersion}) : {outputPath}", "INFO");
        return true;
    } catch (IOException ex) {
        WriteLog($"Échec export ONNX : {ex.Message}", "ERROR");
        return false;
    }
}

function Invoke-GraphQLQuery {
    param([string]$Endpoint, [string]$Query, [hashtable]$Variables = @{}, [string]$BearerToken)
    $body = @{ query = $Query; variables = $Variables } | ConvertTo-Json -Depth 5
    $headers = @{ 'Content-Type' = 'application/json' }
    if ($BearerToken) { $headers['Authorization'] = "Bearer $BearerToken" }
    try {
        $response = Invoke-RestMethod -Uri $Endpoint -Method Post -Headers $headers -Body $body -ErrorAction Stop
        if ($response.errors) { Write-SysLog "Erreur GraphQL : $($response.errors | ConvertTo-Json)" -Level 'ERROR'; throw }
        return $response.data
    } catch {
        Write-SysLog "Échec requête GraphQL : $_" -Level 'ERROR'
        throw
    }
}

public static Vector3 InterpolateVector3(Vector3 start, Vector3 end, float t, bool spherical = false) {
    t = Math.Clamp(t, 0.0f, 1.0f);
    return spherical ? Vector3.Normalize(Vector3.Slerp(start, end, t)) : Vector3.Lerp(start, end, t);
}

public static bool ValidateLuhnAlgorithm(string number) {
    if (string.IsNullOrWhiteSpace(number) || !number.All(char.IsDigit)) return false;
    int sum = 0;
    bool alternate = false;
    for (int i = number.Length - 1; i >= 0; i--) {
        int n = int.Parse(number[i].ToString());
        if (alternate) {
            n *= 2;
            if (n > 9) n -= 9;
        }
        sum += n;
        alternate = !alternate;
    }
    return (sum % 10 == 0);
}

function Get-HardwareTelemetry {
    param([string]$ComputerName = $env:COMPUTERNAME, [switch]$IncludeGPU)
    $cpu = Get-CimInstance -ComputerName $ComputerName -ClassName MSAcpi_ThermalZoneTemperature -Namespace root/wmi
    $tempC = ($cpu.CurrentTemperature - 2732) / 10.0
    $os = Get-CimInstance -ComputerName $ComputerName -ClassName Win32_OperatingSystem
    $ramPct = [math]::Round((($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / $os.TotalVisibleMemorySize) * 100, 1)
    $result = [PSCustomObject]@{ Computer=$ComputerName; CPUTempC=[math]::Round($tempC,1); RAMUsagePct=$ramPct }
    if ($IncludeGPU) {
        # Nécessite souvent un wrapper comme LibreHardwareMonitor CLI
        $result | Add-Member -NotePropertyName 'GPUTempC' -NotePropertyValue 'N/A (Requiert LHM)'
    }
    return $result
}
